            "title": "ชป.กร.ร้อย 924 เข้าพบปะผู้นำชุมชน นายมะกอเซ็ง มีเด็ง ผญบ.ม.3 ต.ปะกาฮะรัง เตรียมพร้อมรับมืออุทกภัยและต้านภัยยาเสพติด",
            "category": "ผู้นำชุมชน / ต.ปะกาฮะรัง",
