            "content": "เมื่อ ๒๙๑๐๓๐ ส.ค.๖๙ ด.ต.ชัยวัฒน์ ศรีสังข์งาม หน.ชป.กร.ร้อย ฉก.ตชด.๙๒๔ พร้อมพวกรวม ๓ นาย เดินทางเข้าพบปะเยี่ยมเยียนผู้นำชุมชน ได้พบปะพูดคุยกับ นายมะกอเซ็ง มีเด็ง ผญบ.ม.๓ ต.ปะกาฮะรังฯ เพื่อประสานการปฏิบัติเตรียมความพร้อมรับมือสถานการณ์อุทกภัย สอบถามสภาพความเป็นอยู่ ปัญหายาเสพติดและเยาวชนกลุ่มเสี่ยงฯ แลกเปลี่ยนข้อมูลข่าวสาร แจ้งเตือนสถานการณ์ในพื้นที่ จชต. รวมถึงสืบสวนหาข่าวความเคลื่อนของกลุ่ม ผกร.ในพื้นที่ ณ ที่ทำการผญบ.ม.๓ ต.ปะกาฮะรัง อ.เมือง จว.ปัตตานี พิกัด ๔๗NQH ๔๗๖๒๗ ๕๕๔๖๒ ผลการปฏิบัติผู้นำชุมชนมีท่าทีและทัศนคติที่ดีต่อเจ้าหน้าที่ ได้รับความร่วมมือและการต้อนรับเป็นอย่างดี เหตุการณ์ปกติ",
